// Рилс #1 на Kling v3 Standard (fal) — сравнение с Veo. Воркфлоу временный.
// Кадры = утверждённые на этапе 1. Звук ВЫКЛ: русскую речь Kling не умеет (только EN/CN),
// голос Рыжа — в CapCut (TTS или свой). На репликах просим «говорящий» рот.
// Цена: $0.084/сек без звука → все 5 клипов (19с) ≈ $1.60.

const STYLE = "2D flat vector cartoon animation. Keep the exact art style of the image for the whole clip: thick clean black outlines, soft cel shading, flat colors. The fox stays identical to the first frame: same face, colors, headband, wristbands, black shorts, bare cream paws. Smooth natural cartoon motion.";
const NEGATIVE = "3D render, Pixar style, realistic fur, photorealism, morphing, body deformation, hernia, bulge or lump on the belly, object merging into the body, extra limbs, extra fingers, distorted face, changing outfit, shoes, sneakers, black paws, subtitles, text, letters, watermark, blur, low quality";
const TALK = "His mouth moves naturally as if he is talking to the viewer.";

// on: false — клип пропустить (не платить повторно за удачный).
const CLIPS = [
  {
    key: '1_hook',
    on: true,
    frame: "https://v3b.fal.media/files/b/0aab9714/Iuz6RGfrSebBNf0CNpqVj_GqMfseGK.png",
    duration: 5,
    talk: true,
    line: "Стоп. Жрёшь по ночам ТЫ — а пузо растёт у МЕНЯ?!",
    action: "The fox takes a bite of the sandwich with his mouth and chews, the sandwich stays in his hand and never touches his belly. Then he looks down at his round belly in shock, looks up at the viewer and complains, outraged, his other paw on his belly.",
  },
  {
    key: '2_intro',
    on: true,
    frame: "https://v3b.fal.media/files/b/0aab9956/j03TEZJ_NWQ3g1ujIDhTg_mhuoPvAs.png",
    duration: 5,
    talk: true,
    line: "Я Рыж. Живу у тебя в Телеграме — и становлюсь таким, как ты.",
    action: "The fox jumps fully out of the glowing phone screen, lands on the desk in front of the phone keeping the same size, then waves at the viewer with a big friendly grin and speaks.",
  },
  {
    key: '5a_result_before',
    on: true,
    frame: "https://v3b.fal.media/files/b/0aab9956/oQF_6cpK9oxtBpyKu24U-_o2Wj8zzb.png",
    duration: 3,
    talk: false,
    line: "",
    action: "The fox does two natural bodyweight squats, straining and puffing, a small sweat drop on his forehead. His round belly stays smooth.",
  },
  {
    key: '5b_result_after',
    on: true,
    frame: "https://v3b.fal.media/files/b/0aab9956/KuCcZyboKHJlcUbU7Y0Kc_tEXEOlDj.png",
    duration: 3,
    talk: true,
    line: "Держишь норму — и пузо уходит. У обоих!",
    action: "The fox flexes his bicep proudly, grins at the viewer and speaks.",
  },
  {
    key: '6_cta',
    on: true,
    frame: "https://v3b.fal.media/files/b/0aab977f/g728kX2AST-SjW-X-Z8JB_iCs7LNBf.png",
    duration: 3,
    talk: true,
    line: "Заведи своего лиса. Не бросай меня, а?",
    action: "The fox winks, then lowers his raised finger to point straight at the camera and speaks with a cheeky pleading grin.",
  },
];

return CLIPS.filter(s => s.on).map(s => ({ json: {
  key: s.key,
  line: s.line,
  image_url: s.frame,
  prompt: [STYLE, s.action, s.talk ? TALK : 'He does not talk.', 'Static camera.'].join(' '),
  negative_prompt: NEGATIVE,
  duration: String(s.duration),
} }));
